#!/usr/bin/env bash
# send200 — send ONE premium test delivery email (creates a sample delivered order).
# emails.js was already upgraded by step200; this only runs the send, with NODE_PATH
# pointed at the app's modules so dotenv/pg resolve from /tmp.
set -uo pipefail
GSZ=/opt/gsz
TO="${1:-ishtiaqmails@gmail.com}"
SJS=$(mktemp /tmp/send200.XXXXXX.js)
base64 -d > "$SJS" <<'SEOF'

SEOF
NODE_PATH="$GSZ/node_modules" node "$SJS" "$TO"
